<?php
declare(strict_types=1);
namespace KodVadAll\Modules\CMS;
use PDO;
use RuntimeException;
use Throwable;
final class CMSController
{
 public static function handle(PDO $db,array $admin):void
 {
  kd_require_permission('site.view');$action=(string)($_GET['action']??'pages');$errors=[];$success='';
  if($_SERVER['REQUEST_METHOD']==='POST'){kd_csrf_check();kd_require_permission('site.manage');try{$f=(string)($_POST['form_action']??'');
   if($f==='page'||$f==='blog'){$title=trim((string)($_POST['title']??''));$slug=self::slug((string)($_POST['slug']??$title));$content=trim((string)($_POST['content']??''));$status=in_array($_POST['status']??'', ['draft','published'],true)?$_POST['status']:'draft';if($title===''||$slug===''||$content==='')throw new RuntimeException('Başlık, URL ve içerik zorunludur.');if($f==='page'){$db->prepare('INSERT INTO site_pages (title,slug,content,meta_title,meta_description,status,created_by,created_at) VALUES (?,?,?,?,?,?,?,NOW())')->execute([$title,$slug,$content,trim((string)($_POST['meta_title']??''))?:null,trim((string)($_POST['meta_description']??''))?:null,$status,(int)$admin['id']]);}else{$db->prepare('INSERT INTO blog_posts (title,slug,excerpt,content,meta_title,meta_description,status,published_at,author_id,created_at) VALUES (?,?,?,?,?,?,?,?,?,NOW())')->execute([$title,$slug,trim((string)($_POST['excerpt']??''))?:null,$content,trim((string)($_POST['meta_title']??''))?:null,trim((string)($_POST['meta_description']??''))?:null,$status,$status==='published'?date('Y-m-d H:i:s'):null,(int)$admin['id']]);}$success='İçerik kaydedildi.';}
   if($f==='menu'){$name=trim((string)($_POST['menu_name']??''));$location=in_array($_POST['location']??'', ['header','footer'],true)?$_POST['location']:'header';if($name==='')throw new RuntimeException('Menü adı zorunludur.');$db->prepare("INSERT INTO site_menus (name,location,status,created_at) VALUES (?,?, 'active',NOW())")->execute([$name,$location]);$success='Menü oluşturuldu.';}
   if($f==='menu_item'){$menu=(int)($_POST['menu_id']??0);$label=trim((string)($_POST['label']??''));$url=trim((string)($_POST['url']??''));if($menu<1||$label===''||$url===''||(!str_starts_with($url,'/')&&!filter_var($url,FILTER_VALIDATE_URL)))throw new RuntimeException('Menü bağlantısı bilgilerini kontrol edin.');$db->prepare("INSERT INTO site_menu_items (menu_id,label,url,target,sort_order,status) VALUES (?,?,?,?,?,'active')")->execute([$menu,$label,$url,in_array($_POST['target']??'', ['_self','_blank'],true)?$_POST['target']:'_self',(int)($_POST['sort_order']??0)]);$success='Menü öğesi eklendi.';}
   if($f==='banner'){$title=trim((string)($_POST['title']??''));$image=trim((string)($_POST['image_url']??''));$link=trim((string)($_POST['link_url']??''));if($title==='')throw new RuntimeException('Banner başlığı zorunludur.');foreach([$image,$link] as $url)if($url!==''&&!filter_var($url,FILTER_VALIDATE_URL))throw new RuntimeException('Banner URL geçersiz.');$db->prepare("INSERT INTO site_banners (title,subtitle,image_url,link_url,position,sort_order,status,created_at) VALUES (?,?,?,?,?,?,'active',NOW())")->execute([$title,trim((string)($_POST['subtitle']??''))?:null,$image?:null,$link?:null,in_array($_POST['position']??'', ['home_hero','home_strip'],true)?$_POST['position']:'home_hero',(int)($_POST['sort_order']??0)]);$success='Banner kaydedildi.';}
   if($f==='settings'){$values=['site_name'=>trim((string)($_POST['site_name']??'')),'site_tagline'=>trim((string)($_POST['site_tagline']??'')),'site_hero_title'=>trim((string)($_POST['site_hero_title']??'')),'site_hero_subtitle'=>trim((string)($_POST['site_hero_subtitle']??'')),'site_contact_email'=>trim((string)($_POST['site_contact_email']??'')),'site_phone'=>trim((string)($_POST['site_phone']??'')),'site_footer_text'=>trim((string)($_POST['site_footer_text']??''))];if($values['site_name']==='')throw new RuntimeException('Site adı zorunludur.');if($values['site_contact_email']!==''&&!filter_var($values['site_contact_email'],FILTER_VALIDATE_EMAIL))throw new RuntimeException('E-posta geçersiz.');$q=$db->prepare('INSERT INTO settings (setting_key,setting_value,updated_at) VALUES (?,?,NOW()) ON DUPLICATE KEY UPDATE setting_value=VALUES(setting_value),updated_at=NOW()');foreach($values as $k=>$v)$q->execute([$k,$v]);$success='Site ayarları kaydedildi.';}
  }catch(Throwable $e){error_log('KodVadAll CMS: '.$e->getMessage());$errors[]=$e instanceof RuntimeException?$e->getMessage():'CMS kaydı tamamlanamadı.';}}
  $pages=$db->query('SELECT * FROM site_pages ORDER BY id DESC')->fetchAll();$menus=$db->query('SELECT * FROM site_menus ORDER BY id DESC')->fetchAll();$menuItems=$db->query('SELECT i.*,m.name menu_name FROM site_menu_items i JOIN site_menus m ON m.id=i.menu_id ORDER BY m.id,i.sort_order')->fetchAll();$banners=$db->query('SELECT * FROM site_banners ORDER BY sort_order,id DESC')->fetchAll();$posts=$db->query('SELECT * FROM blog_posts ORDER BY id DESC')->fetchAll();$settings=[];foreach($db->query("SELECT setting_key,setting_value FROM settings WHERE setting_key LIKE 'site_%'")->fetchAll() as $r)$settings[$r['setting_key']]=$r['setting_value'];
  $pageTitle='E-ticaret Sitesi & CMS';ob_start();require KD_ROOT.'/app/Views/cms/index.php';$content=ob_get_clean();require KD_ROOT.'/app/Views/layouts/admin.php';
 }
 private static function slug(string $s):string{if(function_exists('iconv')){$v=iconv('UTF-8','ASCII//TRANSLIT//IGNORE',$s);if($v!==false)$s=$v;}return trim(preg_replace('/[^a-z0-9]+/','-',strtolower(trim($s)))??'','-');}
}
